var Battery = Number(global.get("Tesla_Y_Data.battery_level"));
var TeslaFull = 80 //estimated KWH with charging effeciency loss
var ChargeLimit = Number(global.get("Tesla_Y_Data.charge_limit_soc"));
var CurrentKWH = TeslaFull * Battery / 100;
var KWHLimit = TeslaFull * ChargeLimit / 100;
var KWHNeeded = KWHLimit - CurrentKWH;

msg.Battery = Battery;
msg.CurrentKWH = CurrentKWH;
msg.KWHLimit = KWHLimit;
msg.KWHNeeded = KWHNeeded;
msg.Hours=Math.round((KWHNeeded*1000/(32*240))*100)/100;
msg.message="Charging at max rate and will finish in " + msg.Hours + " Hours."
return msg;

var short_topic = msg.topic.substring(17);

// Retrieve the global MQTT data object or create a new one if it doesn't exist
var mqttData = global.get("Tesla_Y_Data") || {};

// Update the global MQTT data object with the new payload
mqttData[short_topic] = msg.payload;

// Save the updated object back to the global context
global.set("Tesla_Y_Data", mqttData);

// Update the message topic and return the message
msg.topic = short_topic;
return msg;

var tesla = global.get("Tesla_Y_Data") || {};
var x = Number(tesla.battery_level);
var y = Number(tesla.charge_limit_soc);

function boolish(value) {
    return value === true || value === "true" || value === "on" || value === "ON" || value === 1 || value === "1";
}

function otherTeslaNeedsCharge() {
    var other = global.get("Tesla_3_Data") || {};
    var otherBattery = Number(other.battery_level);
    var otherLimit = Number(other.charge_limit_soc);
    return boolish(other.plugged_in)
        && other.geofence === "Home"
        && Number.isFinite(otherBattery)
        && Number.isFinite(otherLimit)
        && otherBattery < otherLimit;
}

msg.payload = (Number.isFinite(x) && Number.isFinite(y) && x >= y && !otherTeslaNeedsCharge()) ? "same" : "diff";
return msg;

var data = global.get("Tesla_Y_Data") || {};
var previousdata = global.get("Tesla_Y_Previous") || {};
var currentvar = data.battery_level;
var previousvar = previousdata.battery_level; 

msg.arguments = currentvar; // Used downstream

// Two outputs based on the comparison
if (previousvar != currentvar) {
    // Update Tesla_Y_Previous with the new value before returning
    previousdata.battery_level = currentvar;
    global.set('Tesla_Y_Previous', previousdata);

    return [msg, null];
} else {
    return [null, msg];
}

