var data = global.get("Tesla_Y_Data") || {};
var previousdata = global.get("Tesla_Y_Previous") || {};
var currentvar = data.plugged_in;
var previousvar = previousdata.plugged_in;

msg.arguments = currentvar;

function isUnplugged(value) {
    if (typeof value === "boolean") return value === false;
    if (value === 0) return true;
    if (value === null || value === undefined) return false;
    var normalized = String(value).trim().toLowerCase();
    return ["false", "off", "unplugged", "disconnected", "0"].indexOf(normalized) !== -1;
}

function boolish(value) {
    return value === true || value === "true" || value === "on" || value === "ON" || value === 1 || value === "1";
}

function otherTeslaNeedsCharge() {
    var other = global.get("Tesla_3_Data") || {};
    var otherBattery = Number(other.battery_level);
    var otherLimit = Number(other.charge_limit_soc);
    return boolish(other.plugged_in)
        && other.geofence === "Home"
        && Number.isFinite(otherBattery)
        && Number.isFinite(otherLimit)
        && otherBattery < otherLimit;
}

if (previousvar != currentvar) {
    previousdata.plugged_in = currentvar;
    global.set("Tesla_Y_Previous", previousdata);

    if (isUnplugged(currentvar)) {
        msg.payload = "unplugged";
        if (otherTeslaNeedsCharge()) {
            return [null, msg];
        }
        return [msg, null];
    }
}

return [null, msg];

