        let configPayload = {
            unique_id: sensorDetails.sensor_id, device: device, name: sensorDetails.name,
            state_topic: stateTopic, unit_of_measurement: sensorDetails.unit,
            value_template: "{{ value }}", icon: sensorDetails.icon,
            json_attributes_topic: stateTopic
        };
        if (sensorDetails.device_class) { configPayload.device_class = sensorDetails.device_class; }

