    } else if (tonightAmps > 0) {
        amps = tonightAmps;
        mode = "charge_tonight";
        reason = "Charge tonight schedule active";
    } else if (solarAmps > 0) {
        amps = solarAmps;
        mode = "solar";
        reason = "Excess solar available and sustained";
