        ? (now.getTime() - state.chargingSince) / 1000
        : 0;
    const minRuntimeMet = runtimeSeconds >= CFG.MIN_CHARGE_RUN_SECONDS;
    previousMode = state.lastMode || "idle";
    solarHoldAllowed =
        solarCanContinue &&
        availableWatts > 0 &&
