    incomingEntityId,
    incomingEntityState,
    whichTesla,
    vehicleID,
    teslaTelemetryAvailable,
    batteryLevel,
    chargeLimitSOC,
    teslaCapacity,
    solarPW,
    pw,
    evChargingPower,
    totalHome,
    nonEvHouseLoad,
    availableWatts,
    solarAmpsRaw,
    gridOutageRaw,
    gridOutage,
    touBlocked,
    chargeTonight,
    chargeAsap,
    automationDisabled,
    recoveryActive: state.recoveryActive,
    recoveryTarget,
    previousMode,
    solarHoldAllowed,
    powerwallReserve: {
