    return Number.isFinite(n) ? n : null;
}

function powerText(value) {
    const n = Number(value);
    return Number.isFinite(n) ? `${(Math.abs(n) / 1000).toFixed(1)} kW` : "unknown";
}

function voltageText(value) {
    const n = Number(value);
    return Number.isFinite(n) ? `${Math.round(n)} V` : "unknown";
}

function durationText(milliseconds) {
    if (!Number.isFinite(milliseconds) || milliseconds < 0) return null;
    const minutes = Math.max(1, Math.round(milliseconds / 60000));
    if (minutes < 60) return `${minutes} minute${minutes === 1 ? "" : "s"}`;
    const hours = Math.floor(minutes / 60);
    const remainder = minutes % 60;
    return remainder
        ? `${hours}h ${remainder}m`
        : `${hours} hour${hours === 1 ? "" : "s"}`;
}

const attrs = msg.data?.new_state?.attributes || {};
const oldState = msg.data?.old_state || {};
const now = Date.now();

// Establish a baseline without notifying when Node-RED/HA first presents a
// state after a restart or telemetry-unavailable interval.
if (baseline === null) {
    if (current === "on") {
        flow.set(
            "powerwallGridOutageSince",
            parsedTime(msg.data?.new_state?.last_changed) ?? now
        );
    }
    node.status({ fill: "grey", shape: "ring", text: `baseline ${current}` });
    return null;
}

// Defensive duplicate suppression in addition to the HA node's
// outputOnlyOnStateChange setting.
if (baseline === current) return null;

msg.device = global.get("BradPhoneNM") || "pixel8";

if (current === "on") {
    const startedAt = parsedTime(msg.data?.new_state?.last_changed) ?? now;
    flow.set("powerwallGridOutageSince", startedAt);

    const batteryW = Number(attrs.battery_power_w);
    const batteryFlow = Number.isFinite(batteryW)
        ? `${batteryW >= 0 ? "battery discharge" : "battery charging"} ${powerText(batteryW)}`
        : "battery flow unknown";

    msg.title = "Grid power is out";
    msg.priority = 1;
    msg.payload = [
        "The utility grid is down. The Powerwalls are supplying the house.",
        `Grid L1/L2: ${voltageText(attrs.grid_l1_voltage_v)} / ${voltageText(attrs.grid_l2_voltage_v)}.`,
        `Home load ${powerText(attrs.load_power_w)}; solar ${powerText(attrs.solar_power_w)}; ${batteryFlow}.`
    ].join("\n");
    node.status({ fill: "red", shape: "dot", text: "outage alert" });
    return msg;
}

const storedSince = Number(flow.get("powerwallGridOutageSince"));
const oldChanged = parsedTime(oldState.last_changed);
const outageSince = Number.isFinite(storedSince) ? storedSince : oldChanged;
const duration = durationText(now - outageSince);
flow.set("powerwallGridOutageSince", null);

msg.title = "Grid power restored";
msg.priority = 0;
msg.payload = [
    "Utility grid power is back and the Powerwall grid contactor is closed.",
    duration ? `Outage duration: ${duration}.` : null,
    `Grid L1/L2: ${voltageText(attrs.grid_l1_voltage_v)} / ${voltageText(attrs.grid_l2_voltage_v)}.`
].filter(Boolean).join("\n");
node.status({ fill: "green", shape: "dot", text: "restoration alert" });
return msg;
